// [Tool] block_source : valider l'action et la source
// action = block (bloquer), unblock (débloquer) ou list (voir les sources bloquées)
const input = $('TOOL - Start').first().json;
const found = $input.first().json;
const userId = input.user_id;
const asked = String(input.source || '').trim();
const a = String(input.action || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '').trim();

const ACTIONS = {
  block: 'block', bloquer: 'block', masquer: 'block',
  unblock: 'unblock', debloquer: 'unblock', reactiver: 'unblock',
  list: 'list', lister: 'list', liste: 'list',
};
const action = ACTIONS[a] || null;
const known = found.known_sources || [];
const blocked = found.blocked || [];
const base = { user_id: userId, action, source: found.matched || null, blocked };

if (!userId) {
  return [{ json: { ...base, ok: false, message: "Utilisateur non identifié : impossible de modifier les sources." } }];
}
if (!action) {
  return [{ json: { ...base, ok: false, message: `Action inconnue "${input.action || ''}". Valeurs possibles : block, unblock ou list.` } }];
}
if (action === 'list') {
  return [{ json: { ...base, ok: true, message: '' } }];
}
if (!found.matched) {
  return [{ json: { ...base, ok: false, message: `Source "${asked}" introuvable. Sources connues : ${known.join(', ') || 'aucune pour le moment'}.` } }];
}
if (action === 'block' && !blocked.includes(found.matched) && blocked.length >= 20) {
  return [{ json: { ...base, ok: false, message: "Tu as déjà 20 sources bloquées, c'est le maximum. Débloques-en une avant d'en ajouter." } }];
}
return [{ json: { ...base, ok: true, message: '' } }];

// [Tool] block_source : réponse { ok, message, data }
const v = $('TOOL - Validate').first().json;
if (!v.ok) return [{ json: { ok: false, message: v.message } }];

const r = $input.first().json;
let blocked = [...v.blocked];
let message;

if (v.action === 'list') {
  message = blocked.length ? `Sources bloquées : ${blocked.join(', ')}.` : "Tu n'as bloqué aucune source.";
} else if (v.action === 'block') {
  if (r.inserted === 1) {
    blocked.push(v.source);
    message = `La source ${v.source} est bloquée : tu ne recevras plus ses articles.`;
  } else if (blocked.includes(v.source)) {
    message = `La source ${v.source} était déjà bloquée.`;
  } else {
    return [{ json: { ok: false, message: "Le blocage a échoué : rien n'a été modifié." } }];
  }
} else {
  if (r.deleted === 1) {
    blocked = blocked.filter(s => s !== v.source);
    message = `La source ${v.source} est débloquée : ses articles pourront de nouveau t'être envoyés.`;
  } else {
    message = `La source ${v.source} n'était pas bloquée.`;
  }
}
blocked.sort();
return [{ json: { ok: true, message, data: { blocked_sources: blocked } } }];
